<?php
namespace Database\Seeders;
use App\Models\Institution;use Illuminate\Database\Seeder;
class LocationSeeder extends Seeder {public function run():void{$i=Institution::firstOrCreate(['slug'=>'university-of-lagos'],['name'=>'University of Lagos','type'=>'university','timezone'=>'Africa/Lagos','status'=>'active']);$c=$i->campuses()->firstOrCreate(['code'=>'MAIN'],['name'=>'Main Campus','address'=>'Akoka, Lagos','status'=>'active']);$data=['LIB'=>['Main Library',['G'=>['Ground Floor',0,['READ-A'=>'Reading Hall A','ARCH'=>'Archive Corridor','LOBBY'=>'Reception and Lobby']],'F1'=>['First Floor',1,['READ-B'=>'Reading Hall B']]]],'SCI'=>['Science Complex',['G'=>['Ground Floor',0,['LAB'=>'Laboratory Wing']]]],'STC'=>['Student Centre',['G'=>['Ground Floor',0,['EAST'=>'East Wing','WEST'=>'West Wing']]]]];foreach($data as $bc=>$bd){$b=$c->buildings()->firstOrCreate(['code'=>$bc],['name'=>$bd[0],'status'=>'active']);foreach($bd[1] as $fc=>$fd){$f=$b->floors()->firstOrCreate(['code'=>$fc],['name'=>$fd[0],'level_number'=>$fd[1],'status'=>'active']);foreach($fd[2] as $ac=>$an)$f->surveyAreas()->firstOrCreate(['code'=>$ac],['name'=>$an,'area_type'=>'general','status'=>'active']);}}}}
